    try {
      await Promise.all(
        selectedBookingIds.map(id => ApiService.updateAdminAppointment(id, { status }))
      );
      setSelectedBookingIds([]);
      if (reloadDataRef.current) reloadDataRef.current();
      await showAlert(`Selected bookings updated to ${status}!`);
