import React, { useState, useEffect } from 'react';
import { SkeletonTableRows, PaginationBar } from '../components/SharedAdminUI';
import { Check, Trash, Search, MessageSquare, AlertCircle } from 'lucide-react';
import ApiService from '../../../../services/api';
import toast from 'react-hot-toast';

export default function ReviewsTab() {
  const [reviews, setReviews] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(1);
  const limit = 10;

  const fetchReviews = async () => {
    try {
      setIsLoading(true);
      const res = await ApiService.getAdminReviews();
      if (res.success) {
        setReviews(res.data || []);
      }
    } catch (err) {
      toast.error('Failed to load reviews');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchReviews();
  }, []);

  const handleApprove = async (id) => {
    if (!window.confirm("Approve this review for public display?")) return;
    try {
      const res = await ApiService.approveReview(id);
      if (res.success) {
        toast.success("Review approved");
        fetchReviews();
      } else {
        toast.error(res.message || "Failed to approve");
      }
    } catch (e) {
      toast.error("An error occurred");
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this review?")) return;
    try {
      const res = await ApiService.deleteReview(id);
      if (res.success) {
        toast.success("Review deleted");
        fetchReviews();
      } else {
        toast.error(res.message || "Failed to delete");
      }
    } catch (e) {
      toast.error("An error occurred");
    }
  };

  const filteredReviews = reviews.filter(r => 
    (r.name && r.name.toLowerCase().includes(searchQuery.toLowerCase())) ||
    (r.comment && r.comment.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const totalPages = Math.max(1, Math.ceil(filteredReviews.length / limit));
  const pagedReviews = filteredReviews.slice((page - 1) * limit, page * limit);

  return (
    <div className="space-y-6 animate-in fade-in duration-200">
      <div className="flex flex-col md:flex-row justify-between md:items-end gap-4 mb-4">
        <div>
          <h2 className="text-2xl font-bold text-white font-header flex items-center gap-2">
            <MessageSquare className="w-6 h-6 text-brand" />
            Reviews & Testimonials
          </h2>
          <p className="text-sm text-zinc-500 font-medium pt-1">Approve or remove reviews submitted by users</p>
        </div>
      </div>

      <div className="bg-zinc-900/60 rounded-xl border border-zinc-850 p-4 space-y-4 shadow-xl relative overflow-hidden">
        {/* Search */}
        <div className="flex flex-col sm:flex-row gap-4 items-center justify-between">
          <div className="relative w-full sm:max-w-xs">
            <input
              type="text"
              placeholder="Search by name or content..."
              value={searchQuery}
              onChange={e => { setSearchQuery(e.target.value); setPage(1); }}
              className="w-full bg-zinc-950 border border-zinc-800 rounded-lg pl-9 pr-4 py-2 text-sm text-white focus:outline-none focus:border-brand"
            />
            <Search className="w-4 h-4 text-zinc-500 absolute left-3 top-2.5" />
          </div>
        </div>

        {/* Table */}
        <div className="border border-zinc-800 rounded-xl overflow-hidden bg-zinc-950 shadow-inner">
          <div className="overflow-x-auto w-full">
            <table className="w-full text-sm text-left border-collapse min-w-[700px]">
              <thead>
                <tr className="bg-zinc-900/80 text-zinc-400 font-bold border-b border-zinc-800">
                  <th className="p-4">User</th>
                  <th className="p-4">Role</th>
                  <th className="p-4">Rating</th>
                  <th className="p-4 w-1/3">Comment</th>
                  <th className="p-4 text-center">Status</th>
                  <th className="p-4 text-center">Actions</th>
                </tr>
              </thead>
              <tbody>
                {isLoading ? (
                  <SkeletonTableRows rows={3} cols={6} />
                ) : pagedReviews.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="p-12 text-center text-zinc-500 font-medium">
                      No reviews found.
                    </td>
                  </tr>
                ) : (
                  pagedReviews.map(review => (
                    <tr key={review._id} className="border-b border-zinc-850 hover:bg-zinc-900 transition-colors">
                      <td className="p-4 font-semibold text-white">
                        {review.name}
                        {review.userId && <div className="text-[10px] text-zinc-500 font-mono mt-1">{review.userId.email}</div>}
                      </td>
                      <td className="p-4 text-zinc-400">{review.role}</td>
                      <td className="p-4 font-bold text-amber-500">{review.rating} / 5</td>
                      <td className="p-4 text-zinc-300 text-xs line-clamp-2" title={review.comment}>
                        {review.comment}
                      </td>
                      <td className="p-4 text-center">
                        <span className={`px-2.5 py-1 text-[10px] font-bold rounded ${
                          review.isApproved ? 'bg-emerald-955/30 text-emerald-450 border border-emerald-900/40' : 'bg-amber-955/30 text-amber-500 border border-amber-900/40'
                        }`}>
                          {review.isApproved ? 'Approved' : 'Pending'}
                        </span>
                      </td>
                      <td className="p-4 text-center">
                        <div className="flex items-center justify-center gap-2">
                          {!review.isApproved && (
                            <button
                              onClick={() => handleApprove(review._id)}
                              className="p-1.5 bg-emerald-955/20 text-emerald-500 hover:bg-emerald-955/40 hover:text-emerald-400 rounded transition border border-emerald-900/30"
                              title="Approve Review"
                            >
                              <Check className="w-4 h-4" />
                            </button>
                          )}
                          <button
                            onClick={() => handleDelete(review._id)}
                            className="p-1.5 bg-rose-955/20 text-rose-500 hover:bg-rose-955/40 hover:text-rose-400 rounded transition border border-rose-900/30"
                            title="Delete Review"
                          >
                            <Trash className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>

        <PaginationBar page={page} totalPages={totalPages} setPage={setPage} totalItems={filteredReviews.length} limit={limit} />
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import ApiService from '../../../../services/api';
import { User, Trash, Plus, KeyRound, Search, Edit, X, Loader2 } from 'lucide-react';
import { SkeletonTableRows, PaginationBar } from '../components/SharedAdminUI';
import { validateEmail, validateIndianPhone, parseIndianPhone } from '../../../../utils/validation';

export default function StudentManagementTab(props) {

  const { usersDb, setUsersDb, bookingsDb, testResultsDb = [], reloadData, isSuperAdmin, hasUserPermission, getInitials, showAlert, showConfirm, showPrompt, handleExportPDF, handleExportImage, handleExportAptitudeResults, canAddStudents, canEditStudents, canDeleteStudents, isDbLoading } = props;

  const [searchUser, setSearchUser] = useState('');
  const [studentPage, setStudentPage] = useState(1);
  const [studentLimit, setStudentLimit] = useState(10);

  const [isAddUserOpen, setIsAddUserOpen] = useState(false);
  const [isEditUserOpen, setIsEditUserOpen] = useState(false);
  const [userForm, setUserForm] = useState({ id: '', name: '', email: '', password: '', phone: '', schoolName: '', grade: '', guardianName: '', guardianPhone: '', groupCode: '', profilePic: '', locationName: '', latitude: 0, longitude: 0 });
  const [userFormError, setUserFormError] = useState('');
  const [userFormSuccess, setUserFormSuccess] = useState('');
  const [userProfilePicFile, setUserProfilePicFile] = useState(null);
  const [isUserPicUploading, setIsUserPicUploading] = useState(false);
  const [isSavingForm, setIsSavingForm] = useState(false);

  const [viewingStudent, setViewingStudent] = useState(null);
  const [adminCigiDate, setAdminCigiDate] = useState('');
  const [adminCigiTime, setAdminCigiTime] = useState('');
  const [adminCigiNote, setAdminCigiNote] = useState('');
  const [adminCigiEditingId, setAdminCigiEditingId] = useState(null);
  const [adminCigiFile, setAdminCigiFile] = useState(null);
  const [isAdminCigiUploading, setIsAdminCigiUploading] = useState(false);
  const adminCigiFileInputRef = useRef(null);
  // --- Local refs & state for address search (not passed via tabProps) ---
  const userProfilePicRef = useRef(null);
  const [adminUserSearchQuery, setAdminUserSearchQuery] = useState('');
  const [adminUserSearchResults, setAdminUserSearchResults] = useState([]);
  const [isAdminUserSearching, setIsAdminUserSearching] = useState(false);
  const [isAdminUserLocating, setIsAdminUserLocating] = useState(false);

  const handleAdminUserAddressSearch = async () => {
    if (!adminUserSearchQuery || !adminUserSearchQuery.trim()) return;
    setIsAdminUserSearching(true);
    try {
      const res = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(adminUserSearchQuery.trim())}`
      );
      const data = await res.json();
      setAdminUserSearchResults(data);
      if (data.length === 0) {
        import('react-hot-toast').then(m => m.toast.error('No locations found.'));
      }
    } catch (err) {
      console.error('Geocoding error', err);
      import('react-hot-toast').then(m => m.toast.error('Failed to search location.'));
    } finally {
      setIsAdminUserSearching(false);
    }
  };

  const handleAdminUserDetectLocation = () => {
    if (!navigator.geolocation) {
      import('react-hot-toast').then(m => m.toast.error('Geolocation not supported.'));
      return;
    }
    setIsAdminUserLocating(true);
    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`
          );
          const data = await res.json();
          if (data && data.display_name) {
            setUserForm(prev => ({ ...prev, latitude: lat, longitude: lng, locationName: data.display_name }));
            setAdminUserSearchQuery(data.display_name);
          } else {
            setUserForm(prev => ({ ...prev, latitude: lat, longitude: lng }));
          }
        } catch (err) {
          console.error('Reverse geocoding error', err);
          setUserForm(prev => ({ ...prev, latitude: lat, longitude: lng }));
        }
        import('react-hot-toast').then(m => m.toast.success('Location detected!'));
        setIsAdminUserLocating(false);
      },
      (err) => {
        import('react-hot-toast').then(m => m.toast.error('Failed to detect location: ' + err.message));
        setIsAdminUserLocating(false);
      }
    );
  };


  // Filter students based on search query
  const studentsList = usersDb.filter(u => {
    const role = String(u.role || 'USER').toUpperCase();
    if (role !== 'USER' && role !== 'STUDENT') return false;
    const matchesSearch = !searchUser || 
      (u.name && u.name.toLowerCase().includes(searchUser.toLowerCase())) || 
      (u.email && u.email.toLowerCase().includes(searchUser.toLowerCase())) ||
      (u.id && u.id.toLowerCase().includes(searchUser.toLowerCase()));
    return matchesSearch;
  });

  const handleToggleStudentStatus = async (studentId, currentStatus) => {
    if (!hasUserPermission) {
      await showAlert("Access Denied: You do not have permission to manage users.");
      return;
    }
    const student = usersDb.find(u => u.id === studentId);
    if (!student) return;
    const newStatus = currentStatus === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE';

    // Instant local update
    if (setUsersDb) {
      setUsersDb(prev => prev.map(u => u.id === studentId ? { ...u, status: newStatus } : u));
    }
    try {
      await ApiService.updateAdminUser(
        studentId,
        student.name,
        student.email,
        undefined,
        student.role,
        student.permissions,
        student.customRoleTitle,
        newStatus
      );
      if (reloadData) reloadData();
    } catch (err) {
      // Revert if error
      if (setUsersDb) {
        setUsersDb(prev => prev.map(u => u.id === studentId ? { ...u, status: currentStatus } : u));
      }
      await showAlert(err.message || "Failed to update status.");
    }
  };

  const handleCreateUser = async (e) => {
    e.preventDefault();
    if (!hasUserPermission) {
      setUserFormError("Access Denied: You do not have permission to manage users.");
      return;
    }
    setUserFormError('');
    setUserFormSuccess('');

    if (!userForm.name.trim() || !userForm.email.trim() || !userForm.password) {
      setUserFormError("All fields are required.");
      return;
    }

    setIsSavingForm(true);
    try {
      const res = await ApiService.createAdminUser(
        userForm.name.trim(),
        userForm.email.trim(),
        userForm.password,
        'user',
        [],
        '',
        {
          phone: userForm.phone,
          schoolName: userForm.schoolName,
          grade: userForm.grade,
          guardianName: userForm.guardianName,
          guardianPhone: userForm.guardianPhone,
          groupCode: userForm.groupCode,
          locationName: userForm.locationName,
          latitude: userForm.latitude,
          longitude: userForm.longitude
        }
      );
      if (res.success && res.data && setUsersDb) {
        const newRecord = {
          ...res.data,
          role: 'USER',
          status: 'ACTIVE',
          name: userForm.name.trim(),
          email: userForm.email.trim()
        };
        setUsersDb(prev => [newRecord, ...prev]);
      }
      setUserFormSuccess("User created successfully!");
      setUserForm({ id: '', name: '', email: '', password: '', phone: '', schoolName: '', grade: '', guardianName: '', guardianPhone: '', groupCode: '', profilePic: '', locationName: '', latitude: 0, longitude: 0 });
      setUserProfilePicFile(null);
      if (reloadData) reloadData();
      setTimeout(() => {
        setIsAddUserOpen(false);
        setUserFormSuccess('');
      }, 1000);
    } catch (err) {
      setUserFormError(err.message || "Failed to create user.");
    } finally {
      setIsSavingForm(false);
    }
  };

  const handleOpenAddUser = () => {
    setUserForm({ id: '', name: '', email: '', password: '', phone: '', schoolName: '', grade: '', guardianName: '', guardianPhone: '', groupCode: '', profilePic: '', locationName: '', latitude: 0, longitude: 0 });
    setAdminUserSearchQuery('');
    setAdminUserSearchResults([]);
    setUserProfilePicFile(null);
    setUserFormError('');
    setUserFormSuccess('');
    setIsAddUserOpen(true);
  };

  const handleOpenEditUser = (student) => {
    setUserForm({
      id: student.id,
      name: student.name,
      email: student.email,
      password: student.password || '',
      phone: student.phone || '',
      schoolName: student.schoolName || '',
      grade: student.grade || '',
      guardianName: student.guardianName || '',
      guardianPhone: student.guardianPhone || '',
      groupCode: student.groupCode || '',
      profilePic: student.profilePic || student.image || '',
      locationName: student.locationName || '',
      latitude: student.latitude || 0,
      longitude: student.longitude || 0
    });
    setUserProfilePicFile(null);
    setUserFormError('');
    setUserFormSuccess('');
    setIsEditUserOpen(true);
  };

  const handleUpdateUser = async (e) => {
    e.preventDefault();
    if (!hasUserPermission) {
      setUserFormError("Access Denied: You do not have permission to manage users.");
      return;
    }
    setUserFormError('');
    setUserFormSuccess('');

    if (!userForm.name.trim() || !userForm.email.trim()) {
      setUserFormError("Name and Email are required.");
      return;
    }

    if (!validateEmail(userForm.email)) {
      setUserFormError("Please enter a valid email address.");
      return;
    }

    if (userForm.phone && !validateIndianPhone(userForm.phone)) {
      setUserFormError("Please enter a valid 10-digit Indian phone number.");
      return;
    }

    if (userForm.guardianPhone && !validateIndianPhone(userForm.guardianPhone)) {
      setUserFormError("Please enter a valid 10-digit Indian guardian phone number.");
      return;
    }

    setIsSavingForm(true);
    try {
      const res = await ApiService.updateAdminUser(
        userForm.id,
        userForm.name.trim(),
        userForm.email.trim(),
        userForm.password || undefined,
        undefined,
        undefined,
        undefined,
        undefined,
        {
          phone: userForm.phone,
          schoolName: userForm.schoolName,
          grade: userForm.grade,
          guardianName: userForm.guardianName,
          guardianPhone: userForm.guardianPhone,
          groupCode: userForm.groupCode,
          locationName: userForm.locationName,
          latitude: userForm.latitude,
          longitude: userForm.longitude
        }
      );
      let updatedPicUrl = null;
      if (userProfilePicFile) {
        setIsUserPicUploading(true);
        const fd = new FormData();
        fd.append('profilePic', userProfilePicFile);
        const picRes = await ApiService.adminUpdateUserProfilePic(userForm.id, fd);
        if (picRes && picRes.data && picRes.data.profilePic) {
          updatedPicUrl = picRes.data.profilePic;
        }
        setIsUserPicUploading(false);
      }

      // Instant local state update
      if (setUsersDb) {
        setUsersDb(prev => prev.map(u => {
          if (u.id === userForm.id) {
            return {
              ...u,
              name: userForm.name.trim(),
              email: userForm.email.trim(),
              phone: userForm.phone,
              schoolName: userForm.schoolName,
              grade: userForm.grade,
              guardianName: userForm.guardianName,
              guardianPhone: userForm.guardianPhone,
              groupCode: userForm.groupCode,
              locationName: userForm.locationName,
              latitude: userForm.latitude,
              longitude: userForm.longitude,
              profilePic: updatedPicUrl || u.profilePic
            };
          }
          return u;
        }));
      }

      setUserFormSuccess("User details updated!");
      setUserProfilePicFile(null);
      if (reloadData) reloadData();
      setTimeout(() => {
        setIsEditUserOpen(false);
        setUserFormSuccess('');
      }, 1000);
    } catch (err) {
      setIsUserPicUploading(false);
      setUserFormError(err.message || "Failed to update user.");
    } finally {
